export const Api: Story = {
  parameters: {
    docs: {
      description: { story: "Pass `value` and `onValueChange` to control the position from your own state. Any control can then move the carousel, and the carousel reports swipes and key presses back through `onValueChange`. `CarouselIndicator` and `CarouselCounter` follow the position without extra wiring. A new `value` animates only while the carousel is on screen and uncovered; otherwise the carousel jumps straight to it.

```tsx
const [value, setValue] = React.useState(0);

<Carousel aria-label="Workflow" value={value} onValueChange={setValue}>
  <CarouselSlides>...</CarouselSlides>
  <CarouselIndicator />
  <CarouselCounter />
</Carousel>;
```

To build a control inside the carousel, read `useCarousel()`:

```tsx
const JumpToEnd = () => {
  const { state, actions } = useCarousel();

  return <Button onClick={() => actions.goTo(state.count - 1)}>Last</Button>;
};
```" },
      source: { code: ApiSource },
    },
  },
  render: ApiExample,
};

export const Autoplay: Story = {
  parameters: {
    docs: {
      description: { story: "Add `CarouselAutoplay` to advance the slides on a timer. It renders the pause and play button that moving content needs, waits while the carousel is hovered or focused, and stops when someone navigates. Under reduced motion it starts paused. Combine it with `loop` so the carousel keeps going past the last slide. Pair it with `CarouselIndicator` and the current dot fills over `delay`, so readers can see when the next slide comes in; the fill holds while autoplay waits and turns solid once it stops.

```tsx
<Carousel aria-label="Highlights" loop>
  <CarouselSlides>...</CarouselSlides>
  <CarouselAutoplay delay={2000} />
  <CarouselIndicator />
</Carousel>
```" },
      source: { code: AutoplaySource },
    },
  },
  render: AutoplayExample,
};

export const Events: Story = {
  parameters: {
    docs: {
      description: { story: "`onValueChange` receives the new position and a `source` that says what moved the carousel: `button`, `drag`, `focus`, `indicator`, `keyboard`, `autoplay`, or `imperative`. Use it for analytics, or to react only to the person's own navigation.

```tsx
<Carousel
  aria-label="Numbers"
  onValueChange={(value, { source }) => {
    console.log(`Slide ${value + 1} via ${source}`);
  }}
>
  <CarouselSlides>...</CarouselSlides>
</Carousel>
```" },
      source: { code: EventsSource },
    },
  },
  render: EventsExample,
};

export const Lightbox: Story = {
  parameters: {
    docs: {
      description: { story: "`Carousel` and `Lightbox` share the same `value` and `onValueChange` contract, so one state can drive both. Wrap each slide's image in a `LightboxTrigger`. Selecting a slide opens the viewer at that photo, and closing it leaves the carousel on the photo last shown. While the viewer covers the carousel, a new `value` moves the carousel without animation, so it is already at rest when the close transition measures where to land.

```tsx
const [value, setValue] = React.useState(0);

<Lightbox value={value} onValueChange={setValue}>
  <Carousel aria-label="Photos" value={value} onValueChange={setValue}>
    <CarouselSlides>
      <CarouselSlide>
        <LightboxTrigger index={0}>...</LightboxTrigger>
      </CarouselSlide>
    </CarouselSlides>
  </Carousel>
  <LightboxContent aria-label="Photos">...</LightboxContent>
</Lightbox>;
```" },
      source: { code: LightboxSource },
    },
  },
  render: LightboxExample,
};

import * as React from "react";

import { Button } from "@/registry/erbium/ui/button";
import { Card, CardContent } from "@/registry/erbium/ui/card";
import {
  Carousel,
  CarouselCounter,
  CarouselIndicator,
  CarouselNext,
  CarouselPrevious,
  CarouselSlide,
  CarouselSlides,
} from "@/registry/erbium/ui/carousel";

const slides = ["Plan", "Build", "Review", "Ship", "Measure"];

const CarouselApiDemo = () => {
  const [value, setValue] = React.useState(0);

  return (
    <div className="mx-auto flex max-w-xs flex-col items-center gap-4">
      <Carousel aria-label="Workflow" value={value} onValueChange={setValue} className="w-full">
        <CarouselSlides>
          {slides.map((slide) => (
            <CarouselSlide key={slide}>
              <Card className="aspect-square">
                <CardContent className="flex min-h-0 flex-1 items-center justify-center">
                  <span className="text-title font-semibold">{slide}</span>
                </CardContent>
              </Card>
            </CarouselSlide>
          ))}
        </CarouselSlides>
        <CarouselPrevious />
        <CarouselNext />
        <CarouselIndicator />
        <CarouselCounter className="mt-2 block text-center" />
      </Carousel>
      <div className="flex flex-wrap justify-center gap-2">
        {slides.map((slide, index) => (
          <Button
            key={slide}
            size="sm"
            variant={index === value ? "secondary" : "ghost"}
            aria-pressed={index === value}
            onClick={() => {
              setValue(index);
            }}
          >
            {slide}
          </Button>
        ))}
      </div>
    </div>
  );
};

export default CarouselApiDemo;

